-- GENERATED by tools/gen-pg-schema.mjs from the SQLite schema (server/core/schema.js). DO NOT EDIT BY HAND. Frozen once shipped: add 0002_*.sql for later changes.
CREATE EXTENSION IF NOT EXISTS citext SCHEMA public;

-- the ledger is append-only: the same guarantee the SQLite triggers give
CREATE OR REPLACE FUNCTION na_ledger_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'ledger is append-only'; END $$;

CREATE TABLE users (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  username CITEXT NOT NULL UNIQUE,
  pass_hash TEXT,
  is_guest BIGINT NOT NULL DEFAULT 0,
  is_bot BIGINT NOT NULL DEFAULT 0,
  age_confirmed_at BIGINT,
  color TEXT NOT NULL DEFAULT '#2e9b5e',
  created_at BIGINT NOT NULL,
  last_seen BIGINT,
  signup_ip_hash TEXT
, chat_muted_until BIGINT NOT NULL DEFAULT 0);

CREATE TABLE accounts (
  id TEXT PRIMARY KEY,                 -- 'u:<uid>' cash, 's:<uid>' savings, 'sys:<name>' system accounts
  kind TEXT NOT NULL,                  -- 'cash' | 'savings' | 'system'
  user_id BIGINT,
  balance BIGINT NOT NULL DEFAULT 0,  -- materialised; always equals SUM(ledger_entries.amount) (tested)
  allow_negative BIGINT NOT NULL DEFAULT 0,
  CHECK (allow_negative = 1 OR balance >= 0)
);

CREATE TABLE ledger_tx (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  idem_key TEXT UNIQUE,
  reason TEXT NOT NULL,
  ref TEXT,
  user_id BIGINT,
  created_at BIGINT NOT NULL
);

CREATE TABLE ledger_entries (   -- APPEND-ONLY (triggers below block UPDATE/DELETE)
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tx_id BIGINT NOT NULL REFERENCES ledger_tx(id),
  account_id TEXT NOT NULL REFERENCES accounts(id),
  amount BIGINT NOT NULL,
  balance_after BIGINT NOT NULL,
  created_at BIGINT NOT NULL
);

CREATE INDEX ix_le_account ON ledger_entries(account_id, id);
CREATE INDEX ix_le_tx ON ledger_entries(tx_id);
CREATE TABLE player_state (
  user_id BIGINT PRIMARY KEY REFERENCES users(id),
  x DOUBLE PRECISION NOT NULL, z DOUBLE PRECISION NOT NULL, ry DOUBLE PRECISION NOT NULL DEFAULT 0,
  mode TEXT NOT NULL DEFAULT 'walk',
  energy DOUBLE PRECISION NOT NULL, hunger DOUBLE PRECISION NOT NULL, needs_at BIGINT NOT NULL,
  total_shifts BIGINT NOT NULL DEFAULT 0,
  savings_interest_at BIGINT NOT NULL,
  updated_at BIGINT NOT NULL
, city_id TEXT NOT NULL DEFAULT 'lagos-mainland', last_flight_at BIGINT NOT NULL DEFAULT 0, last_boat_at BIGINT NOT NULL DEFAULT 0, mood DOUBLE PRECISION NOT NULL DEFAULT 60, hair TEXT, hair_at BIGINT NOT NULL DEFAULT 0, health DOUBLE PRECISION NOT NULL DEFAULT 100, health_at BIGINT NOT NULL DEFAULT 0, crash_cd_until BIGINT NOT NULL DEFAULT 0, crash_roll_at BIGINT NOT NULL DEFAULT 0);

CREATE TABLE shifts (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id),
  job_id TEXT NOT NULL,
  started_at BIGINT NOT NULL,
  ends_at BIGINT NOT NULL,
  wage BIGINT NOT NULL,
  status TEXT NOT NULL,                -- active | claimed
  claimed_at BIGINT
);

CREATE UNIQUE INDEX ux_one_active_shift ON shifts(user_id) WHERE status='active';
CREATE INDEX ix_shift_user ON shifts(user_id, job_id, claimed_at);
CREATE TABLE property_owner (
  property_id TEXT PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id),
  mode TEXT NOT NULL,                  -- 'rent' | 'own'
  custom_name TEXT,
  next_rent_due BIGINT,
  missed BIGINT NOT NULL DEFAULT 0,
  since BIGINT NOT NULL,
  paid_price BIGINT NOT NULL DEFAULT 0
, name_hidden BIGINT NOT NULL DEFAULT 0, wall_color TEXT NOT NULL DEFAULT 'cream', floor_color TEXT NOT NULL DEFAULT 'oak');

CREATE UNIQUE INDEX ux_one_home_per_user ON property_owner(user_id);
CREATE TABLE property_items (
  property_id TEXT NOT NULL, item_id TEXT NOT NULL, user_id BIGINT NOT NULL, bought_at BIGINT NOT NULL,
  x BIGINT NOT NULL DEFAULT 0, z BIGINT NOT NULL DEFAULT 0, rot BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (property_id, item_id)
);

CREATE TABLE knocks (       -- visitor knock flow: host accepts/declines; unanswered knocks time out (~95 s)
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, property_id TEXT NOT NULL, visitor_id BIGINT NOT NULL, owner_id BIGINT NOT NULL,
  status TEXT NOT NULL,                   -- pending | accepted | declined | expired | cancelled | ended
  created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, decided_at BIGINT
);

CREATE INDEX ix_knock_owner ON knocks(owner_id, status);
CREATE INDEX ix_knock_visitor ON knocks(visitor_id, status);
CREATE TABLE land_plots (
  plot_id TEXT PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), paid_price BIGINT NOT NULL, bought_at BIGINT NOT NULL, last_check_at BIGINT NOT NULL, levies_paid BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE work_tasks (   -- timing mini-game attached to a shift (server picks the target, server clock judges the tap)
  shift_id BIGINT PRIMARY KEY, started_at BIGINT NOT NULL, period_ms BIGINT NOT NULL, target DOUBLE PRECISION NOT NULL, width DOUBLE PRECISION NOT NULL, result TEXT, bonus_pct BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE notifications (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL, kind TEXT NOT NULL, text TEXT NOT NULL, created_at BIGINT NOT NULL, read_at BIGINT
);

CREATE INDEX ix_notif_user ON notifications(user_id, id);
CREATE TABLE chat_messages (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, username TEXT NOT NULL,
  x DOUBLE PRECISION NOT NULL, z DOUBLE PRECISION NOT NULL, text TEXT NOT NULL, created_at BIGINT NOT NULL
, city_id TEXT NOT NULL DEFAULT 'lagos-mainland');

CREATE TABLE audit_log (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor TEXT, action TEXT NOT NULL, detail TEXT, created_at BIGINT NOT NULL
);

CREATE TABLE advertisers (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email TEXT NOT NULL, brand_name TEXT NOT NULL, access_key TEXT NOT NULL UNIQUE, created_at BIGINT NOT NULL
);

CREATE TABLE ad_creatives (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  advertiser_id BIGINT, mime TEXT NOT NULL, bytes BIGINT NOT NULL, width BIGINT NOT NULL, height BIGINT NOT NULL,
  sha256 TEXT NOT NULL, data BYTEA NOT NULL, created_at BIGINT NOT NULL
);

CREATE TABLE ad_campaigns (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  advertiser_id BIGINT NOT NULL REFERENCES advertisers(id),
  creative_id BIGINT NOT NULL REFERENCES ad_creatives(id),
  surface TEXT NOT NULL, tier TEXT NOT NULL, units BIGINT NOT NULL, days BIGINT NOT NULL,
  link_url TEXT NOT NULL, headline TEXT,
  price_net BIGINT NOT NULL, price_vat BIGINT NOT NULL, price_total BIGINT NOT NULL,
  payment_status TEXT NOT NULL DEFAULT 'test_mode_no_payment',
  status TEXT NOT NULL,                -- submitted|auto_checks|human_review|approved|rejected|scheduled|live|completed
  reject_reason TEXT, flags TEXT,
  requested_start BIGINT, start_at BIGINT, end_at BIGINT,
  is_demo BIGINT NOT NULL DEFAULT 0,
  created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL
, city_id TEXT NOT NULL DEFAULT 'lagos-mainland');

CREATE INDEX ix_camp_status ON ad_campaigns(status);
CREATE TABLE ad_transitions (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, campaign_id BIGINT NOT NULL, from_status TEXT, to_status TEXT NOT NULL,
  actor TEXT NOT NULL, note TEXT, created_at BIGINT NOT NULL
);

CREATE TABLE ad_assignments (   -- which boards a campaign sits on, and its rotation position (0-3)
  campaign_id BIGINT NOT NULL, slot_id TEXT NOT NULL, position BIGINT NOT NULL,
  PRIMARY KEY (campaign_id, slot_id)
);

CREATE TABLE ad_impressions (   -- VALID (filtered-in) impressions only; unique per player per creative per window
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  campaign_id BIGINT NOT NULL, slot_id TEXT NOT NULL, user_id BIGINT NOT NULL, win BIGINT NOT NULL,
  pct BIGINT, ms BIGINT, created_at BIGINT NOT NULL,
  UNIQUE (user_id, campaign_id, win)
);

CREATE TABLE ad_stats (         -- daily counters. gross = every claim received; valid = passed validation + IVT filter
  campaign_id BIGINT NOT NULL, day TEXT NOT NULL,
  gross BIGINT NOT NULL DEFAULT 0, valid BIGINT NOT NULL DEFAULT 0,
  taps_gross BIGINT NOT NULL DEFAULT 0, taps_valid BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (campaign_id, day)
);

CREATE TABLE ad_filter_reasons (
  campaign_id BIGINT NOT NULL, kind TEXT NOT NULL, reason TEXT NOT NULL, n BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (campaign_id, kind, reason)
);

CREATE TABLE ad_taps (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, campaign_id BIGINT NOT NULL, user_id BIGINT NOT NULL,
  valid BIGINT NOT NULL, reason TEXT, created_at BIGINT NOT NULL
);

CREATE INDEX ix_taps ON ad_taps(campaign_id, user_id, created_at);
CREATE TABLE reports (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, reporter_id BIGINT NOT NULL, kind TEXT NOT NULL,       -- house_name | chat | ad_creative
  target_ref TEXT NOT NULL, target_user_id BIGINT, reason TEXT NOT NULL, detail TEXT, snapshot TEXT,
  status TEXT NOT NULL DEFAULT 'open',                  -- open | actioned | dismissed
  created_at BIGINT NOT NULL, resolved_at BIGINT, resolved_by TEXT, resolution TEXT,
  UNIQUE (reporter_id, kind, target_ref)
);

CREATE INDEX ix_reports_status ON reports(status, id);
CREATE INDEX ix_reports_target ON reports(kind, target_ref);
CREATE TABLE user_blocks (               -- mute = I do not see them; block = mute + they cannot DM/knock/sit with me
  blocker_id BIGINT NOT NULL, blocked_id BIGINT NOT NULL, kind TEXT NOT NULL, created_at BIGINT NOT NULL,
  PRIMARY KEY (blocker_id, blocked_id)
);

CREATE INDEX ix_blocks_blocked ON user_blocks(blocked_id);
CREATE TABLE game_matches (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, venue_id TEXT NOT NULL, station_id TEXT NOT NULL, kind TEXT NOT NULL,   -- whot | ludo
  p1 BIGINT NOT NULL, p2 BIGINT, stake BIGINT NOT NULL DEFAULT 0, status TEXT NOT NULL,                       -- waiting | active | finished | cancelled
  state TEXT, turn_user BIGINT, winner BIGINT, result TEXT, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, deadline_at BIGINT
);

CREATE INDEX ix_match_station ON game_matches(venue_id, station_id, status);
CREATE INDEX ix_match_p1 ON game_matches(p1, status);
CREATE INDEX ix_match_p2 ON game_matches(p2, status);
CREATE TABLE game_players (        -- seats at a table (2 for Whot, 2 to 4 for Ludo); out=1 once someone has resigned/timed out of an active game
  match_id BIGINT NOT NULL, user_id BIGINT NOT NULL, seat BIGINT NOT NULL, out BIGINT NOT NULL DEFAULT 0, PRIMARY KEY (match_id, user_id)
);

CREATE INDEX ix_gp_user ON game_players(user_id);
CREATE TABLE game_scores (
  week BIGINT NOT NULL, kind TEXT NOT NULL, user_id BIGINT NOT NULL, wins BIGINT NOT NULL DEFAULT 0, losses BIGINT NOT NULL DEFAULT 0, draws BIGINT NOT NULL DEFAULT 0, points BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (week, kind, user_id)
);

CREATE TABLE player_cars (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, model TEXT NOT NULL, paid BIGINT NOT NULL, bought_at BIGINT NOT NULL, active BIGINT NOT NULL DEFAULT 0,
  serviced_at BIGINT, serviced_until BIGINT                 -- Meco: last service time (condition resets) and when the short service perk ends
, damage BIGINT NOT NULL DEFAULT 0);

CREATE INDEX ix_cars_user ON player_cars(user_id);
CREATE TABLE house_loves (
  property_id TEXT NOT NULL, user_id BIGINT NOT NULL, day TEXT NOT NULL, created_at BIGINT NOT NULL, PRIMARY KEY (property_id, user_id, day)
);

CREATE TABLE room_events (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, property_id TEXT NOT NULL, user_id BIGINT NOT NULL, username TEXT NOT NULL, kind TEXT NOT NULL, text TEXT, created_at BIGINT NOT NULL
);

CREATE INDEX ix_room_events ON room_events(property_id, id);
CREATE TABLE casual_runs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, kind TEXT NOT NULL, seed BIGINT NOT NULL, state TEXT, status TEXT NOT NULL DEFAULT 'open',  -- open | done | abandoned
  score BIGINT NOT NULL DEFAULT 0, reward BIGINT NOT NULL DEFAULT 0, day TEXT NOT NULL, started_at BIGINT NOT NULL, finished_at BIGINT
);

CREATE INDEX ix_casual_user ON casual_runs(user_id, kind, id);
CREATE TABLE scores_cache (id BIGINT PRIMARY KEY CHECK (id = 1), day TEXT NOT NULL, calls BIGINT NOT NULL DEFAULT 0, payload TEXT, source TEXT, good_at BIGINT NOT NULL DEFAULT 0, tried_at BIGINT NOT NULL DEFAULT 0, next_at BIGINT NOT NULL DEFAULT 0, error TEXT, error_code TEXT);

CREATE TABLE boat_trips (user_id BIGINT PRIMARY KEY, from_stop TEXT NOT NULL, to_stop TEXT NOT NULL, state TEXT NOT NULL, fare BIGINT NOT NULL, cross_ms BIGINT NOT NULL, called_at BIGINT NOT NULL, boat_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, arrive_at BIGINT NOT NULL DEFAULT 0);

CREATE TABLE stadium_tickets (user_id BIGINT NOT NULL, venue_id TEXT NOT NULL, day TEXT NOT NULL, created_at BIGINT NOT NULL, PRIMARY KEY (user_id, venue_id, day));

CREATE TABLE casual_daily (user_id BIGINT NOT NULL, day TEXT NOT NULL, earned BIGINT NOT NULL DEFAULT 0, plays BIGINT NOT NULL DEFAULT 0, PRIMARY KEY (user_id, day));

CREATE TABLE flights (user_id BIGINT PRIMARY KEY, from_city TEXT NOT NULL, to_city TEXT NOT NULL, state TEXT NOT NULL, fare BIGINT NOT NULL, departs_at BIGINT NOT NULL, arrive_at BIGINT NOT NULL, created_at BIGINT NOT NULL);

CREATE TABLE friendships (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_a BIGINT NOT NULL, user_b BIGINT NOT NULL, requested_by BIGINT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending',          -- pending | accepted | declined | removed
  created_at BIGINT NOT NULL, responded_at BIGINT,
  CHECK (user_a < user_b), CHECK (requested_by IN (user_a, user_b)),
  UNIQUE (user_a, user_b)
);

CREATE INDEX ix_friend_a ON friendships(user_a, status);
CREATE INDEX ix_friend_b ON friendships(user_b, status);
CREATE TABLE phone_settings (
  user_id BIGINT PRIMARY KEY,
  dnd BIGINT NOT NULL DEFAULT 0,                  -- do not disturb: calls go straight to "missed", messages are silent
  calls_from TEXT NOT NULL DEFAULT 'friends',      -- friends | nobody
  messages_from TEXT NOT NULL DEFAULT 'friends',   -- friends | anyone (anyone = today's behaviour for plain DMs)
  voice_notes_from TEXT NOT NULL DEFAULT 'friends',-- friends | nobody
  show_presence BIGINT NOT NULL DEFAULT 1,        -- friends can see online/at-home dot
  ringtone TEXT NOT NULL DEFAULT 'default',
  voice_consent_at BIGINT,                        -- when the player accepted the microphone/voice notice (see spec 9.1)
  updated_at BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE phone_threads (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_a BIGINT NOT NULL, user_b BIGINT NOT NULL,
  created_at BIGINT NOT NULL, last_message_id BIGINT, last_message_at BIGINT,
  CHECK (user_a < user_b), UNIQUE (user_a, user_b)
);

CREATE TABLE phone_messages (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  thread_id BIGINT NOT NULL, sender_id BIGINT NOT NULL,
  kind TEXT NOT NULL,                              -- text | voice | system (e.g. "Missed call")
  body TEXT,                                       -- text content (already through filter.screen) or system text
  voice_id BIGINT,                                -- -> voice_notes.id when kind='voice'
  created_at BIGINT NOT NULL, deleted_at BIGINT  -- soft delete (sender delete, moderation removal)
);

CREATE INDEX ix_pmsg_thread ON phone_messages(thread_id, id);
CREATE TABLE phone_reads (           -- read cursor per user per thread (unread badges)
  thread_id BIGINT NOT NULL, user_id BIGINT NOT NULL, last_read_message_id BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (thread_id, user_id)
);

CREATE TABLE voice_notes (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  owner_id BIGINT NOT NULL, thread_id BIGINT NOT NULL,
  mime TEXT NOT NULL,                              -- audio/webm;codecs=opus | audio/mp4 | audio/ogg;codecs=opus (allow-list, spec 7.3)
  bytes BIGINT NOT NULL, duration_ms BIGINT NOT NULL,
  storage_key TEXT NOT NULL UNIQUE,                -- path or object key, never user-supplied
  sha256 TEXT NOT NULL,
  waveform TEXT,                                   -- optional: ~48 small ints as JSON, for the bubble
  status TEXT NOT NULL DEFAULT 'ready',            -- ready | removed (moderation) | expired (retention)
  created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, removed_at BIGINT, removed_reason TEXT
);

CREATE INDEX ix_vn_owner ON voice_notes(owner_id, created_at);
CREATE INDEX ix_vn_expiry ON voice_notes(status, expires_at);
CREATE TABLE phone_calls (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  caller_id BIGINT NOT NULL, callee_id BIGINT NOT NULL,
  state TEXT NOT NULL,                             -- ringing | active | ended   (terminal detail in end_reason)
  end_reason TEXT,                                 -- completed | declined | missed | cancelled | busy | dnd | blocked | failed | timeout
  created_at BIGINT NOT NULL, answered_at BIGINT, ended_at BIGINT, duration_s BIGINT,
  ice_path TEXT                                    -- host | srflx | relay (from getStats at the end; tells us how often TURN is needed). nullable
);

CREATE INDEX ix_calls_caller ON phone_calls(caller_id, id);
CREATE INDEX ix_calls_callee ON phone_calls(callee_id, id);
CREATE INDEX ix_calls_open ON phone_calls(state);
CREATE TABLE phone_apps (
  id TEXT PRIMARY KEY,                             -- e.g. 'wallet', 'jobs', or a sponsor slug
  kind TEXT NOT NULL,                              -- builtin | sponsored
  title TEXT NOT NULL, icon TEXT NOT NULL,         -- emoji or creative id
  target_url TEXT,                                 -- sponsored: tap goes through /api/go for counting
  campaign_id BIGINT,                             -- -> ad_campaigns.id (moderation + billing reuse)
  starts_at BIGINT, ends_at BIGINT, enabled BIGINT NOT NULL DEFAULT 1
);

CREATE TABLE payment_intents (   -- one row per attempt to collect real money (TEST MODE in this build)
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ref TEXT NOT NULL UNIQUE,                    -- our reference, also sent to the provider
  idem_key TEXT UNIQUE,
  purpose TEXT NOT NULL,                       -- topup | ad_campaign
  user_id BIGINT, advertiser_id BIGINT, campaign_id BIGINT,
  provider TEXT NOT NULL,
  net_kobo BIGINT NOT NULL, vat_kobo BIGINT NOT NULL, total_kobo BIGINT NOT NULL, fee_est_kobo BIGINT NOT NULL,
  credit BIGINT NOT NULL DEFAULT 0,           -- game naira credited when paid (topup)
  email TEXT,                                  -- needed by the provider and for the VAT receipt; nothing else about the payer is kept
  status TEXT NOT NULL,                        -- created | pending | paid | failed | expired | review | partially_refunded | refunded
  authorization_url TEXT, provider_txn_id TEXT, provider_fee_kobo BIGINT, note TEXT,
  paid_at BIGINT, ledger_tx_id BIGINT, refunded_kobo BIGINT NOT NULL DEFAULT 0, credit_reversed BIGINT NOT NULL DEFAULT 0,
  created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL
);

CREATE INDEX ix_pi_user ON payment_intents(user_id, created_at);
CREATE INDEX ix_pi_status ON payment_intents(status, created_at);
CREATE INDEX ix_pi_campaign ON payment_intents(campaign_id);
CREATE TABLE payment_events (    -- every webhook / verify / sweep that touched a payment, kept as evidence
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ref TEXT, source TEXT NOT NULL, event TEXT, signature_ok BIGINT, provider_event_id TEXT,
  payload_sha256 TEXT UNIQUE,                  -- a re-delivered webhook has the same bytes, so it hits this and is a no-op
  outcome TEXT NOT NULL, detail TEXT, created_at BIGINT NOT NULL
);

CREATE INDEX ix_pe_ref ON payment_events(ref);
CREATE TABLE payment_refunds (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  intent_ref TEXT NOT NULL, idem_key TEXT UNIQUE,
  amount_kobo BIGINT NOT NULL, credit_reversed BIGINT NOT NULL DEFAULT 0, reason TEXT, requested_by TEXT NOT NULL,
  status TEXT NOT NULL,                        -- requested | processed | pending_manual | failed
  attempts BIGINT NOT NULL DEFAULT 0, provider_refund_id TEXT, last_error TEXT,
  created_at BIGINT NOT NULL, settled_at BIGINT
);

CREATE INDEX ix_pr_ref ON payment_refunds(intent_ref);
CREATE INDEX ix_pr_status ON payment_refunds(status);
CREATE TABLE age_verifications (     -- one row per player: the latest standing outcome
  user_id BIGINT PRIMARY KEY,
  result TEXT NOT NULL,                            -- pass | fail
  verified_at BIGINT NOT NULL,
  provider TEXT NOT NULL                           -- which service attested it (no vendor chosen yet: 'mock' today)
);

CREATE TABLE age_sessions (          -- a check in progress or recently finished; the vendor's own opaque id, nothing about the person
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL, session_ref TEXT NOT NULL UNIQUE, provider TEXT NOT NULL,
  state TEXT NOT NULL,                             -- pending | pass | fail | inconclusive | expired
  created_at BIGINT NOT NULL, done_at BIGINT
);

CREATE INDEX ix_age_sess_user ON age_sessions(user_id, created_at);
CREATE TABLE car_parking (
    user_id BIGINT PRIMARY KEY, car_id BIGINT NOT NULL, lot_id TEXT NOT NULL, bay BIGINT NOT NULL, x DOUBLE PRECISION NOT NULL, z DOUBLE PRECISION NOT NULL, ry DOUBLE PRECISION NOT NULL, parked_at BIGINT NOT NULL, fee BIGINT NOT NULL DEFAULT 0
  );

CREATE UNIQUE INDEX ux_parking_bay ON car_parking(lot_id, bay);
CREATE TABLE crash_events (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, at BIGINT NOT NULL, token TEXT, state TEXT NOT NULL, hit BIGINT NOT NULL DEFAULT 0,
    reason TEXT, roll DOUBLE PRECISION, vtype TEXT, mode TEXT, x DOUBLE PRECISION, z DOUBLE PRECISION, damage DOUBLE PRECISION, car_id BIGINT, car_damage BIGINT, fee BIGINT, expires_at BIGINT
  );

CREATE INDEX ix_crash_user ON crash_events(user_id, id);

CREATE TRIGGER le_no_update BEFORE UPDATE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION na_ledger_append_only();
CREATE TRIGGER le_no_delete BEFORE DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION na_ledger_append_only();
CREATE TRIGGER ltx_no_update BEFORE UPDATE ON ledger_tx FOR EACH ROW EXECUTE FUNCTION na_ledger_append_only();
CREATE TRIGGER ltx_no_delete BEFORE DELETE ON ledger_tx FOR EACH ROW EXECUTE FUNCTION na_ledger_append_only();
